package glitch

import data.glitch_lib

# Privilege escalation and superuser indicators
privileged_indicators := {"privileged", "elevated", "privileged_mode", "security_context", "impersonation"}

superuser_values := {"root", "administrator", "system", "superuser", "0", "\\[root\\]", "admin"}

run_as_indicators := {"run_as", "run_as_user", "run_as_group", "user", "container_user"}

capability_indicators := {"add_capabilities", "capabilities", "cap_add", "cap_drop", "drop_capabilities"}

host_indicators := {"host_network", "host_pid", "host_ipc", "host_path", "host_uts", "host_userspace"}

# Check for privileged=true or similar
is_privileged_true(attr) {
    attr.name == privileged_indicators[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
} else {
    attr.name == privileged_indicators[_]
    attr.value.ir_type == "String"
    lower(attr.value.value) == "true"
}

# Check for run_as_user: 0 or run_as_user: root
is_run_as_superuser(attr) {
    attr.name == run_as_indicators[_]
    attr.value.ir_type == "String"
    lower(attr.value.value) == superuser_values[_]
} else {
    attr.name == run_as_indicators[_]
    attr.value.ir_type == "Integer"
    attr.value.value == 0
}

# Check for allow_privilege_escalation: true (risky when combined with other factors)
is_privilege_escalation_allowed(attr) {
    attr.name == "allow_privilege_escalation"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Check for caps including ALL or SYS_ADMIN
has_dangerous_capabilities(attr) {
    attr.name == capability_indicators[_]
    attr.value.ir_type == "Array"
    val := attr.value.value[_]
    val.ir_type == "String"
    upper(val.value) == "ALL"
} else {
    attr.name == capability_indicators[_]
    attr.value.ir_type == "Array"
    val := attr.value.value[_]
    val.ir_type == "String"
    contains(upper(val.value), "SYS_ADMIN")
} else {
    attr.name == capability_indicators[_]
    attr.value.ir_type == "String"
    contains(upper(attr.value.value), "ALL")
}

# Check for host namespace sharing
is_host_namespace_shared(attr) {
    attr.name == host_indicators[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
} else {
    attr.name == host_indicators[_]
    attr.value.ir_type == "String"
    lower(attr.value.value) == "true"
}

# Check for read_only_root_filesystem: false (absence of hardening)
is_read_only_disabled(attr) {
    attr.name == "read_only_root_filesystem"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Check for seccomp/apparmor disabled
is_seccomp_disabled(attr) {
    attr.name == ("seccomp_profile" | "apparmor_profile")
    attr.value.ir_type == "String"
    contains(lower(attr.value.value), "unconfined")
}

# Check for run_as_non_root: false
is_run_as_non_root_disabled(attr) {
    attr.name == "run_as_non_root"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Accumulate privilege risks for an atomic unit
privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_privileged_true(attr)
    reason := "privileged_mode_enabled"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_run_as_superuser(attr)
    reason := "running_as_superuser"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_privilege_escalation_allowed(attr)
    reason := "privilege_escalation_allowed"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    has_dangerous_capabilities(attr)
    reason := "dangerous_capabilities_assigned"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_host_namespace_shared(attr)
    reason := "host_namespace_shared"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_read_only_disabled(attr)
    reason := "read_only_root_filesystem_disabled"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_seccomp_disabled(attr)
    reason := "seccomp_apparmor_disabled"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_run_as_non_root_disabled(attr)
    reason := "run_as_non_root_disabled"
}

# Generic wildcard/permission patterns in strings
has_wildcard_permissions(attr) {
    attr.value.ir_type == "String"
    regex.match("(?i)(\\*|all|\\*:.*|\\*:.*:\\*|administratoraccess|owner|contributor|fullcontrol)", attr.value.value)
}

# Check for NOPASSWD or sudo without restrictions
has_sudo_bypass(attr) {
    attr.value.ir_type == "String"
    regex.match("(?i)(nopasswd|sudo.*all|\\(ALL\\)|!requiretty)", attr.value.value)
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    has_wildcard_permissions(attr)
    reason := "wildcard_permissions_detected"
}

privilege_risks[reason] {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    has_sudo_bypass(attr)
    reason := "sudo_bypass_detected"
}

# Main rule: Detect execution with unnecessary privileges
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Collect all risk factors for this atomic unit
    risks := {r | privilege_risks[r] with node as node}

    # Trigger if at least 2 risk factors or privileged mode with host access
    count(risks) >= 2

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": sprintf("Execution with Unnecessary Privileges - Multiple privilege escalation indicators detected (%s). (CWE-250)", [concat(", ", sort(risks))])
    }
}

# Single high-risk indicator: privileged mode with any host namespace
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_privileged_true(attr)

    other := attrs[_]
    is_host_namespace_shared(other)

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Privileged mode combined with host namespace sharing creates excessive privilege exposure. (CWE-250)"
    }
}

# Single high-risk indicator: running as root with privilege escalation allowed
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_users[_]

    attrs := glitch_lib.all_attributes(node)

    some i
    attr1 := attrs[i]
    is_run_as_superuser(attr1)

    some j
    attr2 := attrs[j]
    i != j
    is_privilege_escalation_allowed(attr2)

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Running as root with privilege escalation explicitly allowed. (CWE-250)"
    }
}

